import assert from 'node:assert/strict';
import { mkdir, writeFile } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import { sdkOptions } from '../../src/server/sdk-options.ts';
import { SdkExecution } from '../../src/server/sdk-execution.ts';
import { runDirectory } from './run-directory.mjs';

// A source generated by the documented synthetic profiling script, never a user model.
const source = resolve(process.argv[2] || '');
assert.ok(
  source.includes(
    `${process.platform === 'win32' ? '\\' : '/'}large-rhino-sync${process.platform === 'win32' ? '\\' : '/'}`,
  ),
);
const directory = runDirectory('rhino-large-import');
await mkdir(directory, { recursive: true });
const options = sdkOptions(directory);
if (process.env.VIDE_TEST_RHINO_PLUGIN)
  options.plugin = resolve(process.env.VIDE_TEST_RHINO_PLUGIN);
const sdk = new SdkExecution({ ...options, tools: {}, origin: () => '' });
const began = Date.now();
const result = await sdk.importFile(source, () => {});
assert.equal(result.objects.length, 10713);
assert.equal(result.scene.length, 10713);
assert.equal(new Set(result.objects.map((o) => o.nativeId)).size, 10713);
assert.equal(result.scene.filter((o) => o.nativeType === 'InstanceReference').length, 13);
assert.equal(result.verified, true);
assert.equal(result.displayCoverage.omitted, 13);
const evidence = {
  passed: true,
  nativeReadbackVerified: true,
  objects: result.objects.length,
  seconds: (Date.now() - began) / 1000,
  displayBytes: Buffer.byteLength(JSON.stringify(result)),
  blockInstances: 13,
  displayCoverage: result.displayCoverage,
  directory,
};
await writeFile(join(directory, 'result.json'), JSON.stringify(evidence, null, 2));
console.log(JSON.stringify(evidence));
